'use strict';
let data,current='overview',selected=new Set(['lenovo-t14g6-a','hp-e840g11','apple-air13m4']);
const el=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,s='')=>v==null?'Unverified':esc(v)+s,yn=v=>v==null?'Unverified':v?'Yes':'No';
const sourceLinks=ids=>ids.map(id=>{const s=data.sources.find(s=>s.id===id);return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener">[${esc(id)}]</a>`:''}).join(' ');
async function api(path,body){const r=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
function error(e){el('notice').className='error';el('notice').textContent=e.message||String(e);}
function clearError(){el('notice').textContent='';el('notice').className='';}
const titles={overview:['The business laptop landscape.','Understand the trade-offs. Find the gaps. Follow the evidence.'],compare:['Compare with context.','Platform specifications, transparent requirements, and traceable evidence.'],gaps:['Where does the portfolio fit?','Screen the sample against specific customer requirements.'],changes:['Follow the evidence over time.','Historical launches, reviewed updates, and source checks.'],ask:['Ask a business question.','Ground answers in manufacturer evidence and SQL analysis.'],sources:['Every insight has a source.','Review the evidence, add research, and export for Power BI.']};
function navigate(view){if(!titles[view])return;current=view;location.hash=view;document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});el('title').textContent=titles[view][0];el('subtitle').textContent=titles[view][1];clearError();if(data)({overview,compare,gaps,changes,ask,sources})[view]();}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(v!==current)navigate(v)});
function metric(label,value,sub){return `<article><small>${label}</small><strong>${value}</strong><span>${sub}</span></article>`}
function productTable(ps,choose=false){return `<div class="tablewrap"><table><thead><tr>${choose?'<th>SELECT</th>':''}<th>PRODUCT / PLATFORM</th><th>MAX MEMORY</th><th>STARTING WEIGHT</th><th>RAM UPGRADABLE</th><th>EVIDENCE</th></tr></thead><tbody>${ps.map(p=>`<tr>${choose?`<td><input type="checkbox" aria-label="Compare ${esc(p.family+' '+p.variant)}" data-product="${p.id}" ${selected.has(p.id)?'checked':''}></td>`:''}<td><div class="brandline">${esc(p.brand)}</div><strong>${esc(p.family)}</strong><small>${esc(p.variant)}</small></td><td>${fmt(p.max_ram_gb,' GB')}</td><td>${fmt(p.weight_kg,' kg')}</td><td>${yn(p.ram_upgradeable)}</td><td>${sourceLinks(p.source_ids)}<small>${p.evidence_coverage_pct}% field coverage</small></td></tr>`).join('')||'<tr><td colspan="6">No products match these filters.</td></tr>'}</tbody></table></div>`}
function overview(){const families=new Set(data.products.map(p=>p.brand+p.family)).size,avg=Math.round(data.products.reduce((s,p)=>s+p.evidence_coverage_pct,0)/data.products.length);el('content').innerHTML=`<div class="metrics">${metric('PRODUCT FAMILIES',families,`${data.products.length} platform variants in the sample`)}${metric('BRANDS COVERED',data.brands.length,'Focused competitive research universe')}${metric('EVIDENCE COVERAGE',avg+'%','Across seven specification fields')}${metric('CURRENT OFFERS',data.prices.filter(p=>p.kind!=='launch').length,'Historical launch prices kept separate')}</div><div class="grid"><section class="panel"><div class="split"><h2>Portability at a glance</h2><span class="badge">Starting weight · kg</span></div>${data.products.filter(p=>p.weight_kg!=null).sort((a,b)=>a.weight_kg-b.weight_kg).map(p=>`<div class="barrow"><span>${esc(p.family.replace('ThinkPad ','').replace('MacBook ','').replace('ExpertBook ',''))}<small style="display:block">${esc(p.variant)}</small></span><div class="bartrack"><div class="bar" style="width:${p.weight_kg/1.8*100}%"></div></div><span>${p.weight_kg}</span></div>`).join('')}<p class="quiet">Lower means lighter. Unknown weights are excluded. Maximum memory may require a heavier configuration.</p></section><section class="panel"><h2>Research signals</h2><div class="insight"><span class="badge">Configuration matters</span><h3 style="margin-top:10px">One family, two memory strategies.</h3><p>T14 Gen 6 Arrow Lake supports 64GB with memory slots; Lunar Lake offers fixed memory up to 32GB.</p>${sourceLinks(['S2'])}</div><div class="insight"><span class="badge">Sample opportunity</span><h3 style="margin-top:10px">Serviceability narrows the shortlist.</h3><p>Screen for 64GB, upgradable RAM, and starting weight ≤1.5kg. Unknown fields remain unresolved.</p><button class="button" id="see-gaps">Explore portfolio fit →</button></div><div class="insight"><span class="badge">Pricing evidence needed</span><p>One verified historical launch observation is available. Add matching current configurations before drawing price/value conclusions.</p>${sourceLinks(['S9'])}</div></section></div><section class="panel"><div class="split"><h2>The research universe</h2><button class="button" id="see-compare">Open comparison →</button></div>${productTable(data.products)}</section><p class="footer-note">Verified ${esc(data.as_of)} · ${esc(data.scope)}</p>`;el('see-gaps').onclick=()=>navigate('gaps');el('see-compare').onclick=()=>navigate('compare');}
function compare(){el('content').innerHTML=`<section class="panel"><div class="toolbar"><label>Search<br><input id="search" type="search" placeholder="Brand, model or platform"></label><label>Brand<br><select id="brand"><option value="">All brands</option>${data.brands.map(b=>`<option>${esc(b.brand)}</option>`).join('')}</select></label><label>Sort by<br><select id="sort"><option value="name">Product name</option><option value="weight">Lowest starting weight</option><option value="ram">Highest memory capacity</option></select></label></div><p class="quiet">Select up to four platform variants for side-by-side comparison.</p><div id="catalog"></div></section><section class="panel"><h2>Your comparison</h2><div id="comparison"></div></section><section class="panel"><h2>Price observations</h2><p>Compare equivalent configurations in the same market, currency, date window and tax basis. Launch prices are historical positioning evidence.</p><div class="tablewrap"><table><thead><tr><th>PRODUCT</th><th>AMOUNT</th><th>TYPE / DATE</th><th>CONFIGURATION</th><th>SOURCE</th></tr></thead><tbody>${data.prices.map(p=>`<tr><td>${esc(data.products.find(x=>x.id===p.product_id)?.family||p.product_id)}</td><td>${esc(p.currency)} ${p.amount.toLocaleString()}<small>${esc(p.market)}</small></td><td>${esc(p.kind)}<small>${esc(p.observed_on)}</small></td><td>${esc(p.configuration)}<small>Tax: ${esc(p.tax_basis)}</small></td><td>${sourceLinks([p.source_id])}</td></tr>`).join('')}</tbody></table></div><details><summary>Add a sourced price observation</summary><form id="priceform"><div class="toolbar"><label class="field">Product<select name="product_id">${data.products.map(p=>`<option value="${p.id}">${esc(p.family+' / '+p.variant)}</option>`).join('')}</select></label><label class="field">Amount<input name="amount" type="number" min="0.01" step="0.01" required></label><label class="field">Currency<input name="currency" value="USD" pattern="[A-Z]{3}" required></label></div><div class="toolbar"><label class="field">Market<input name="market" required></label><label class="field">Date<input type="date" name="observed_on" required></label><label class="field">Type<select name="kind"><option value="retail">Retail offer</option><option value="quote">Quote</option><option value="launch">Historical launch</option></select></label><label class="field">Source<select name="source_id">${data.sources.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.title)}</option>`).join('')}</select></label></div><label class="field">Exact configuration<input name="configuration" placeholder="SKU, CPU, installed RAM, SSD, display, warranty" required></label><label class="field">Tax basis<input name="tax_basis" placeholder="Includes tax / excludes tax / not specified" required></label><p class="quiet">Add new evidence through the Evidence library first. The source must be linked to this product.</p><button class="primary">Save observation</button></form></details></section>`;const redraw=()=>{let ps=data.products.filter(p=>(!el('brand').value||p.brand===el('brand').value)&&(p.brand+' '+p.family+' '+p.variant).toLowerCase().includes(el('search').value.toLowerCase()));if(el('sort').value==='weight')ps.sort((a,b)=>(a.weight_kg??Infinity)-(b.weight_kg??Infinity));if(el('sort').value==='ram')ps.sort((a,b)=>(b.max_ram_gb??-1)-(a.max_ram_gb??-1));el('catalog').innerHTML=productTable(ps,true);document.querySelectorAll('[data-product]').forEach(c=>c.onchange=()=>{if(c.checked&&selected.size>=4){c.checked=false;error(Error('Choose up to four products. Deselect one first.'));return}c.checked?selected.add(c.dataset.product):selected.delete(c.dataset.product);clearError();renderComparison()})};['search','brand','sort'].forEach(id=>el(id).oninput=redraw);redraw();renderComparison();el('priceform').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.amount=Number(d.amount);try{await api('price',d);data=await api('data');compare()}catch(e){error(e)}};}
function renderComparison(){const ps=data.products.filter(p=>selected.has(p.id));if(!ps.length){el('comparison').innerHTML='<div class="empty">Select products above to compare them.</div>';return}const attributes=[['Platform','variant'],['Maximum supported memory','max_ram_gb',' GB'],['Starting weight','weight_kg',' kg'],['Memory upgradable','ram_upgradeable'],['Maximum supported storage','max_storage_gb',' GB'],['Built-in Ethernet','ethernet'],['Battery option','battery_wh',' Wh'],['Display diagonal','screen_in',' in'],['Configuration notes','notes']];el('comparison').innerHTML=`<div class="tablewrap"><table><thead><tr><th>ATTRIBUTE</th>${ps.map(p=>`<th>${esc(p.brand)}<br>${esc(p.family)}</th>`).join('')}</tr></thead><tbody>${attributes.map(([label,key,unit])=>`<tr><td>${label}</td>${ps.map(p=>`<td>${['ram_upgradeable','ethernet'].includes(key)?yn(p[key]):fmt(p[key],unit||'')}</td>`).join('')}</tr>`).join('')}<tr><td>Evidence</td>${ps.map(p=>`<td>${sourceLinks(p.source_ids)}</td>`).join('')}</tr></tbody></table></div><div class="note">Maximum memory is not installed memory. Starting weights are not guaranteed for maximum-memory configurations. Battery capacity is not measured battery life. Unknown means unverified.</div>`;}
function evaluate(p,ram,weight,upgrade,ethernet){const checks=[p.max_ram_gb==null?'unknown':p.max_ram_gb>=ram?'pass':'fail',p.weight_kg==null?'unknown':p.weight_kg<=weight?'pass':'fail'];if(upgrade)checks.push(p.ram_upgradeable==null?'unknown':p.ram_upgradeable===1?'pass':'fail');if(ethernet)checks.push(p.ethernet==null?'unknown':p.ethernet===1?'pass':'fail');return{checks,status:checks.includes('fail')?'fail':checks.includes('unknown')?'unknown':'pass',matched:checks.filter(c=>c==='pass').length};}
function badge(s){return `<span class="badge ${s}">${{pass:'Candidate',fail:'No match',unknown:'Unresolved'}[s]}</span>`}
function gaps(){el('content').innerHTML=`<section class="panel"><h2>Sample coverage by customer requirement</h2><div class="tablewrap"><table class="matrix"><thead><tr><th>BRAND</th><th>TRAVEL<br>≥32GB · ≤1.3kg</th><th>SERVICEABLE FLEET<br>≥64GB · ≤1.5kg · RAM slots</th><th>COMPACT WIRED FLEET<br>≥32GB · ≤1.4kg · RAM slots · Ethernet</th></tr></thead><tbody>${data.coverage.map(b=>`<tr><td><strong>${esc(b.brand)}</strong></td>${b.scenarios.map(s=>`<td>${badge(s.status)}<small>${s.candidates} candidate variants</small></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="note">“No match” is a gap in this research sample, not the manufacturer's full portfolio. A candidate needs SKU verification. “Unresolved” means missing evidence could change the result.</div></section><section class="panel"><h2>Build your own requirement screen</h2><div class="toolbar"><label>Minimum supported RAM<br><select id="ram"><option>16</option><option selected>32</option><option>64</option><option>128</option></select> GB</label><label>Maximum starting weight<br><input id="weight" type="number" min="0.5" max="5" step="0.05" value="1.4"> kg</label><label><input id="upgrade" type="checkbox"> Require upgradable RAM</label><label><input id="ethernet" type="checkbox"> Require built-in Ethernet</label></div><div id="screen-results"></div><details><summary>How the analysis works</summary><p>Each requirement is checked independently. A failed known requirement excludes the platform. Missing evidence produces an unresolved result when no requirement has failed. No weighted marketing score or performance benchmark is inferred.</p></details></section>`;const redraw=()=>{const ram=Number(el('ram').value),weight=Number(el('weight').value);if(!Number.isFinite(weight)||weight<.5||weight>5){el('screen-results').innerHTML='<p>Enter a weight between 0.5 and 5 kg.</p>';return}const rs=data.products.map(p=>({p,...evaluate(p,ram,weight,el('upgrade').checked,el('ethernet').checked)})).sort((a,b)=>({pass:0,unknown:1,fail:2}[a.status]-{pass:0,unknown:1,fail:2}[b.status]));el('screen-results').innerHTML=`<p class="status">${rs.filter(r=>r.status==='pass').length} candidates · ${rs.filter(r=>r.status==='unknown').length} unresolved · ${rs.filter(r=>r.status==='fail').length} excluded</p><div class="tablewrap"><table><thead><tr><th>PLATFORM</th><th>REQUIREMENTS MET</th><th>RESULT</th><th>EVIDENCE</th></tr></thead><tbody>${rs.map(r=>`<tr><td><strong>${esc(r.p.brand+' '+r.p.family)}</strong><small>${esc(r.p.variant)}</small></td><td>${r.matched} / ${r.checks.length}</td><td>${badge(r.status)}</td><td>${sourceLinks(r.p.source_ids)}</td></tr>`).join('')}</tbody></table></div>`};['ram','weight','upgrade','ethernet'].forEach(id=>el(id).oninput=redraw);redraw();}
function changes(){el('content').innerHTML=`<div class="grid"><section class="panel"><h2>Historical product launches</h2>${data.launches.map(l=>`<div class="source"><span class="badge">${esc(l.announced_on)}</span><h3 style="margin-top:12px">${esc(l.title)}</h3><p>${esc(l.summary)}</p>${sourceLinks([l.source_id])}</div>`).join('')}<p class="quiet">Curated history, not an exhaustive market-news feed.</p></section><section class="panel"><h2>Reviewed specification changes</h2>${data.changes.length?data.changes.map(c=>`<div class="source"><strong>${esc(c.product_id)} · ${esc(c.field)}</strong><p>${esc(c.old_value)} → ${esc(c.new_value)}</p><small>${esc(c.changed_at)}</small> ${sourceLinks([c.source_id])}</div>`).join(''):'<div class="empty">No reviewed specification changes yet.<br>Research imports record field-level changes here.</div>'}</section></div><section class="panel"><h2>Source freshness checks</h2><p>Check availability and content fingerprints. A changed page is a review signal; specifications are not silently rewritten.</p><div class="toolbar"><select id="check-source" aria-label="Source to check">${data.sources.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.title)}</option>`).join('')}</select><button class="primary" id="run-check">Check source</button></div><div id="check-output" role="status"></div><div class="tablewrap"><table><thead><tr><th>CHECKED AT (UTC)</th><th>SOURCE</th><th>STATUS</th><th>DETAIL</th></tr></thead><tbody>${data.checks.map(c=>`<tr><td>${esc(c.checked_at)}</td><td>${sourceLinks([c.source_id])}</td><td>${esc(c.status)}</td><td>${esc(c.detail)}</td></tr>`).join('')||'<tr><td colspan="4">No source checks yet. The first successful fetch becomes the baseline.</td></tr>'}</tbody></table></div></section>`;el('run-check').onclick=async()=>{const b=el('run-check');b.disabled=true;b.textContent='Checking…';try{const r=await api('check',{source_ids:[el('check-source').value]});data=await api('data');if(current!=='changes')return;changes();el('check-output').textContent=r.results.map(r=>r.status+': '+r.detail).join(' · ')}catch(e){error(e);b.disabled=false;b.textContent='Check source'}};}
async function ask(){el('content').innerHTML=`<section class="panel"><div class="split"><h2>Research assistant</h2><span id="model-status" class="badge">Checking local model…</span></div><div class="chips">${['Where are the portfolio gaps?','Which laptops have the lowest starting weight?','Can we identify a price/value winner?','What product launches are recorded?'].map(q=>`<button data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="askform"><label for="question">Your question</label><textarea id="question" maxlength="2000" required placeholder="Which products support a serviceable business fleet?"></textarea><div class="split"><label><input type="checkbox" id="use-model"> Use local language model</label><button class="primary" id="askbutton">Find evidence →</button></div></form><p class="quiet">Evidence search works without a model. Check generated answers against the cited sources.</p></section><section class="panel" id="answer-panel"><div class="empty">Ask about portfolio fit, memory, portability, pricing, or recorded launches.</div></section>`;const submit=async()=>{const b=el('askbutton');if(b.disabled)return;b.disabled=true;b.textContent='Reading evidence…';clearError();try{const r=await api('ask',{question:el('question').value,use_llm:el('use-model').checked});if(current!=='ask')return;el('answer-panel').innerHTML=`<span class="badge">${esc(r.mode)}</span><div class="answer" style="margin-top:20px">${esc(r.answer)}</div><h3 style="margin-top:25px">Evidence available for verification</h3>${r.citations.map(s=>`<div class="source"><a href="${esc(s.url)}" target="_blank" rel="noopener">[${s.id}] ${esc(s.title)} ↗</a><p>${esc(s.summary)}</p></div>`).join('')}`}catch(e){error(e)}finally{if(current==='ask'){el('askbutton').disabled=false;el('askbutton').textContent='Find evidence →'}}};el('askform').onsubmit=e=>{e.preventDefault();submit()};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{el('question').value=b.dataset.question;submit()});try{const s=await api('llm');if(current!=='ask')return;el('model-status').textContent=s.ready?'Local model ready':'Evidence search ready';el('use-model').disabled=!s.ready;}catch(e){if(current==='ask')el('model-status').textContent='Evidence search ready'}}
function sources(){el('content').innerHTML=`<section class="panel"><div class="split"><h2>Manufacturer evidence library</h2><span class="badge">${data.sources.length} sources</span></div><p>Summaries are curated research notes, not verbatim document copies. Verification dates describe research collection, not availability.</p>${data.sources.map(s=>`<div class="source"><div class="split"><a href="${esc(s.url)}" target="_blank" rel="noopener"><strong>[${s.id}] ${esc(s.title)} ↗</strong></a><span class="badge">${esc(s.kind)}</span></div><p>${esc(s.summary)}</p><small>${esc(s.publisher)} · Verified ${esc(s.verified_on)}</small></div>`).join('')}</section><section class="panel"><h2>SQL and Power BI exports</h2><p>The Power BI project reads exported CSV files. Refresh the report after updating research.</p><div class="chips">${['products','brands','sources','prices','launches','changes','source_checks'].map(t=>`<a class="button" href="/api/export?table=${t}">↓ ${t.replace('_',' ')} CSV</a>`).join('')}</div><button class="primary" id="pbi-export">Update all Power BI data files</button><span id="export-status" role="status"></span></section><section class="panel"><h2>Import reviewed research</h2><p>Import JSON using the supplied seed format. Use new source IDs to preserve evidence history. Changed product fields appear in the audit log; existing products are matched by ID.</p><form id="importform"><label>Research JSON <input type="file" accept=".json,application/json" id="importfile" required></label><button class="primary">Import reviewed research</button></form><p class="quiet">Manufacturer HTTPS sources only. Use null for unverified specifications. Existing source IDs cannot be overwritten.</p><div id="import-status" role="status"></div></section>`;el('pbi-export').onclick=async()=>{try{await api('export-powerbi',{});el('export-status').textContent=' Updated. Open Power BI and select Refresh.'}catch(e){error(e)}};el('importform').onsubmit=async e=>{e.preventDefault();try{const f=el('importfile').files[0];if(f.size>1_000_000)throw Error('Research file must be smaller than 1 MB.');const r=await api('import',JSON.parse(await f.text()));data=await api('data');sources();el('import-status').textContent=r.imported+' product records imported.'}catch(e){error(e)}};}
async function boot(){try{data=await api('data');navigate(titles[location.hash.slice(1)]?location.hash.slice(1):'overview');}catch(e){error(Error('The local research service is not ready. Open Start Portfolio Lens, then refresh this page.'));return}if(document.modelContext?.registerTool){try{await document.modelContext.registerTool({name:'screen_laptop_portfolio',description:'Show the portfolio requirements screen and return matching platform variants from this curated sample.',inputSchema:{type:'object',properties:{minimum_ram_gb:{type:'number',minimum:1},maximum_weight_kg:{type:'number',minimum:.5,maximum:5}},required:['minimum_ram_gb','maximum_weight_kg'],additionalProperties:false},annotations:{readOnlyHint:true},execute:async input=>{if(typeof input?.minimum_ram_gb!=='number'||typeof input?.maximum_weight_kg!=='number'||input.minimum_ram_gb<=0||input.maximum_weight_kg<.5||input.maximum_weight_kg>5)throw Error('Invalid requirements');navigate('gaps');const s=el('ram');if(!Array.from(s.options).some(o=>Number(o.value)===input.minimum_ram_gb))s.add(new Option(String(input.minimum_ram_gb),String(input.minimum_ram_gb)));s.value=String(input.minimum_ram_gb);el('weight').value=String(input.maximum_weight_kg);el('weight').dispatchEvent(new Event('input'));return data.products.map(p=>({id:p.id,...evaluate(p,input.minimum_ram_gb,input.maximum_weight_kg,false,false)}));}})}catch(e){/* Optional capability; primary interface remains available. */}}}
boot();
